class AdminProductModal(discord.ui.Modal, title="📦 تحديد المنتج للتقييم"):
    product_input = discord.ui.TextInput(
        label="اسم المنتج أو الخدمة المقدمة للعميل",
        placeholder="مثال: كامري 2024، سكربت مابات، مود أسلحة...",
        required=True,
        max_length=100
    )

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer()
        prod = self.product_input.value.strip()
        await send_review_prompt_to_channel(interaction.channel, prod)
        try:
            if interaction.message:
                await interaction.message.delete()
        except:
            pass

